function plainText(s){return String(s||"").replace(/<br\s*\/?>/gi," ").replace(/<[^>]+>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/\s+/g," ").trim()}
function titleTokens(str,hl){const out=[];if(!str||!String(str).trim())return out;
  if(!/<\/?(span|b|strong|i|em|u|br|p|div)\b/i.test(str)){let a=-1,b=-1;if(hl){a=str.indexOf(hl);if(a>=0)b=a+hl.length}
    String(str).split(/\n/).forEach((line,li,arr)=>{const re=/\S+/g;let m;const off=arr.slice(0,li).join("\n").length+(li?1:0);
      while((m=re.exec(line))){const idx=off+m.index;out.push({parts:[{t:m[0],st:{hl:a>=0&&idx>=a&&idx<b}}]})}
      if(li<arr.length-1&&out.length)out[out.length-1].br=true});return out}
  if(typeof DOMParser==="undefined")return titleTokens(plainText(str),hl);
  const doc=new DOMParser().parseFromString("<div>"+sanitizeRich(str)+"</div>","text/html");let space=true;
  const push=(w,st)=>{if(!space&&out.length&&!out[out.length-1].br)out[out.length-1].parts.push({t:w,st});else out.push({parts:[{t:w,st}]});space=false};
  (function walk(n,st){n.childNodes.forEach(c=>{
    if(c.nodeType===3){const txt=c.nodeValue.replace(/ /g," ");if(/^\s/.test(txt))space=true;const ws=txt.split(/\s+/).filter(Boolean);ws.forEach((w,k)=>{if(k>0)space=true;push(w,st)});if(/\s$/.test(txt))space=true;return}
    if(c.nodeType!==1)return;const tg=c.tagName;
    if(tg==="BR"){if(out.length)out[out.length-1].br=true;space=true;return}
    const s2=Object.assign({},st);if(tg==="B"||tg==="STRONG")s2.b=true;if(tg==="I"||tg==="EM")s2.i=true;if(tg==="U")s2.u=true;
    const cm=(c.getAttribute("class")||"").match(/\btc-(\w+)/);if(cm)s2.cls="tc-"+cm[1];
    walk(c,s2);if(/^(P|H2|H3|H4|LI|BLOCKQUOTE|DIV)$/.test(tg)&&out.length){out[out.length-1].br=true;space=true}})})(doc.body.firstChild,{});
  if(out.length)delete out[out.length-1].br;return out}
function tokPart(p){let s=escH(p.t);if(p.st.b)s=`<b>${s}</b>`;if(p.st.i)s=`<i>${s}</i>`;if(p.st.u)s=`<u>${s}</u>`;if(p.st.cls)s=`<span class="${p.st.cls}">${s}</span>`;if(p.st.hl)s=`<em>${s}</em>`;return s}
function tokRender(toks){return toks.map(t=>t.parts.map(tokPart).join("")+(t.br?"<br>":"")).join(" ").replace(/<br> /g,"<br>")}
let _mctx=null;
function fitTitle(h1,toks,opt){opt=opt||{};if(!h1||!toks.length)return;const align=opt.align||"justify";
  if(align!=="justify"){h1.style.fontSize="";h1.style.textAlign=align;h1.style.textAlignLast="";h1.innerHTML=tokRender(toks);return}
  h1.style.textAlign="";try{_mctx=_mctx||document.createElement("canvas").getContext("2d")}catch(e){}if(!_mctx){h1.innerHTML=tokRender(toks);return}
  h1.style.fontSize="";const cs=getComputedStyle(h1),base=parseFloat(cs.fontSize),W=h1.clientWidth;if(!base||!W){h1.innerHTML=tokRender(toks);return}
  const fw=cs.fontWeight,ff=cs.fontFamily;let best=null;const ks=opt.fixed?[1]:[];if(!opt.fixed)for(let k=1.1;k>=0.8;k-=0.02)ks.push(k);
  for(const k of ks){const size=base*k,ls=-.01*size;
    const ws=toks.map(t=>t.parts.reduce((a,p)=>{_mctx.font=`${p.st.i?"italic ":""}${p.st.b?Math.max(700,+fw||400):fw} ${size}px ${ff}`;return a+_mctx.measureText(p.t).width+ls*p.t.length},0));
    _mctx.font=`${fw} ${size}px ${ff}`;const sp=_mctx.measureText(" ").width-.02*size,n=ws.length;
    const cost=new Array(n+1).fill(Infinity),from=new Array(n+1).fill(-1),mx=new Array(n+1).fill(0);cost[0]=0;
    for(let j=1;j<=n;j++)for(let i=j-1;i>=0;i--){let bad=false;for(let q=i;q<j-1;q++)if(toks[q].br){bad=true;break}if(bad)break;
      let L=0;for(let q=i;q<j;q++)L+=ws[q];L+=(j-i-1)*sp;if(L>W){if(j-i===1)L=W;else break}
      const last=j===n,forced=!!toks[j-1].br,cnt=j-i;let c,st=0;
      if(last){c=L<W*.35?4:0}else if(forced){c=0}else{if(cnt<2)continue;st=(W-L)/(cnt-1)/size;c=Math.pow(st*10,3)}
      if(i>0&&!isFinite(cost[i]))continue;
      if(cost[i]+c<cost[j]){cost[j]=cost[i]+c;from[j]=i;mx[j]=Math.max(mx[i],st)}}
    if(!isFinite(cost[n]))continue;const brk=[];for(let j=n;j>0;j=from[j])brk.unshift([from[j],j]);
    const cand={size,brk,max:mx[n]};if(!best||cand.max<best.max-.005)best=cand;if(cand.max<=.2&&brk.length>1){best=cand;break}}
  if(!best){h1.innerHTML=tokRender(toks);return}
  if(!opt.fixed)h1.style.fontSize=best.size.toFixed(2)+"px";
  h1.innerHTML=best.brk.map(([i,j],x)=>{const lastL=x===best.brk.length-1||(toks[j-1].br&&j-i<2);return`<span class="ln${lastL?" last":""}">${toks.slice(i,j).map(t=>t.parts.map(tokPart).join("")).join(" ")}</span>`}).join(" ")}

