function typoVal(typo,role){const r=TYPO_ROLES.find(x=>x[0]===role),t=(typo||{})[role]||{},d=DEFAULTS.typography[role]||{};
  const size=+t.size>0?+t.size:(+d.size||r[2]),w=+t.weight||+d.weight||400,font=t.font||d.font||"dax";return{font,weight:w,size,k:size/r[2]}}
function googleHref(typo){const fams={};TYPO_ROLES.forEach(([r])=>{const v=typoVal(typo,r),f=FONTS[v.font];if(f&&f.g){(fams[f.g]=fams[f.g]||{f,ws:new Set()}).ws.add(v.weight)}});
  const parts=Object.values(fams).map(({f,ws})=>{const want=[...new Set([400,...ws].map(w=>f.w.reduce((a,b)=>Math.abs(b-w)<Math.abs(a-w)?b:a)))].sort((a,b)=>a-b);return"family="+encodeURIComponent(f.g).replace(/%20/g,"+")+":wght@"+want.join(";")});
  return parts.length?"https://fonts.googleapis.com/css2?"+parts.join("&")+"&display=swap":""}
function applyTypo(root,typo){const ls=(k,d)=>{const v=(typo||{})[k];return(v===""||v==null||isNaN(+v)?d:+v)/100+"em"};root.style.setProperty("--ls-title",ls("lsTitle",-1));root.style.setProperty("--ls-label",ls("lsLabel",12));root.style.setProperty("--ls-body",ls("lsBody",0));TYPO_ROLES.forEach(([r])=>{const v=typoVal(typo,r);root.style.setProperty(`--${r}-f`,typoFont(v.font));root.style.setProperty(`--${r}-w`,v.weight);root.style.setProperty(`--${r}-k`,v.k.toFixed(4))});
  const href=googleHref(typo);let l=document.getElementById("typoFonts");
  if(href){if(!l){l=document.createElement("link");l.id="typoFonts";l.rel="stylesheet";document.head.appendChild(l)}if(l.getAttribute("href")!==href)l.setAttribute("href",href)}else if(l)l.remove()}
