const PKEY="cdm-port-of-beira-pass";
const clone=o=>JSON.parse(JSON.stringify(o));
function merge(base,over){if(Array.isArray(base))return Array.isArray(over)?over:base;if(base&&typeof base==="object"){const r={...base};if(over&&typeof over==="object")for(const k in over)r[k]=k in base?merge(base[k],over[k]):over[k];return r}return over===undefined?base:over}
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const get=(o,p)=>p.split(".").reduce((a,k)=>a==null?a:a[k],o);
function set(o,p,v){const ks=p.split(".");let a=o;for(let i=0;i<ks.length-1;i++){if(a[ks[i]]==null)a[ks[i]]={};a=a[ks[i]]}a[ks[ks.length-1]]=v}
const PT=x=>x&&typeof x==="object"?((cmsLang==="en"?x.en:x.pt)||x.pt||x.en||""):(x||"");
const LOC=()=>cmsLang==="en"?"en-GB":"pt-PT";
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
function toast(t){$("#toastRoot").innerHTML='<div class="toast">'+esc(cmsLang==="en"?trText(String(t)):t)+'</div>';clearTimeout(toast.t);toast.t=setTimeout(()=>$("#toastRoot").innerHTML="",2800)}

