function trText(s){const k=s.trim();if(!k)return s;let tr=CMS_EN[k];if(tr==null)for(const [r,rp] of CMS_RX){const m=k.match(r);if(m){tr=rp(m);break}}if(tr==null)return s;return s.replace(k,tr)}
function trDOM(root){if(cmsLang!=="en"||!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement&&n.parentElement.closest("[contenteditable],textarea,script,style,.notr,[data-typoprev]")?2:1});
  const ns=[];while(w.nextNode())ns.push(w.currentNode);ns.forEach(n=>{const t=trText(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t});
  root.querySelectorAll("[placeholder],[aria-label],[title]").forEach(e=>{if(e.closest("[contenteditable]")&&!e.matches("[contenteditable]"))return;["placeholder","aria-label","title"].forEach(at=>{const v=e.getAttribute(at);if(v&&!(at==="placeholder"&&e.closest(".uirow"))){const t=trText(v);if(t!==v)e.setAttribute(at,t)}})})}

