function hydrate(o){return merge(clone(DEFAULTS),clone(o||{}))}
/* pequenas actualizações automáticas ao conteúdo já publicado (aplicadas uma vez; ficam no rascunho para publicar) */
function migrate(d,src){const done=d._mig=Array.isArray(src&&src._mig)?src._mig.slice():[],msgs=[];
  if(!done.includes("berth-link")){done.push("berth-link");const has=(d.footerMenus||[]).some(m=>(m.links||[]).some(l=>l.page==="berth-plan"));
    if(!has&&d.pages["berth-plan"]){const fm=(d.footerMenus||[]).find(m=>/useful|úteis|uteis/i.test((m.title&&(m.title.en+" "+m.title.pt))||""))||(d.footerMenus||[])[d.footerMenus.length-1];
      if(fm){const L2=fm.links=fm.links||[],k=L2.findIndex(l=>l.page==="port-position");L2.splice(k>=0?k+1:L2.length,0,{label:T("Berth Plan","Plano de Atracação"),page:"berth-plan"});msgs.push("Plano de atracação acrescentado aos Links úteis")}}}
  if(!done.includes("weights-medium")){done.push("weights-medium");const T2=d.typography=d.typography||{};let n=0;["heroTitle","pageTitle","section","sub","numbers","label","nav"].forEach(r=>{if(T2[r]&&+T2[r].weight>=700){T2[r].weight=500;n++}});if(n)msgs.push("Títulos e números passaram a peso médio (500)")}
  if(!done.includes("news5")){done.push("news5");if(d.home&&String(d.home.newsCount||"3")==="3"){d.home.newsCount="5";msgs.push("Bloco de notícias passou a mostrar até 5")}}
  if(!done.includes("albums")){done.push("albums");if(!(d.albums||[]).length&&(d.gallery||[]).length){d.albums=[{id:"geral",on:true,title:T("General","Geral"),summary:T("",""),cat:"",date:"",cover:"",photos:d.gallery}];d.gallery=[];msgs.push("As fotografias da galeria passaram para a colecção Geral")}}
  if(!done.includes("popup-list")){done.push("popup-list");const P=d.popup;if(P&&!Array.isArray(P.items)){const had=P.image||(P.title&&(P.title.en||P.title.pt))||(P.text&&(P.text.en||P.text.pt));
    const it={on:!!P.enabled,name:T("Banner","Banner"),recur:"once"};["layout","image","imageMobile","alt","title","text","cta","page","url","start","end","freq","delay"].forEach(k=>{if(P[k]!==undefined)it[k]=P[k]});
    d.popup={enabled:true,items:had?[it]:[]};if(had)msgs.push("O banner passou para o calendário anual")}}
  if(!done.includes("no3d")){done.push("no3d");const H=d.home&&d.home.hero;if(H&&(!H.bg||H.bg==="3d")){const hasV=(H.videos||[]).some(v=>v&&(typeof v==="string"?v:v.src));H.bg=hasV?"video":"image";msgs.push("Cena 3D removida: o topo passa a usar "+(hasV?"os vídeos":"a imagem de fundo"))}}
  return msgs}
function strip(d){const c=clone(d);delete c.updatedAt;return c}

