function fText(p,l,h,ph){return`<div class="f"><label for="${id(p)}">${l}</label><input type="text" id="${id(p)}" data-p="${p}" value="${esc(get(draft,p))}" placeholder="${esc(ph||"")}">${hint(h)}</div>`}
