function ovVals(ov,home){const pc=(v,d)=>v===""||v==null||isNaN(+v)?d:+v;return{L:pc(ov.left,90),R:pc(ov.right,home?20:40),B:pc(ov.bottom,home?100:0),C:ov.color==="black"?"0,0,0":"28,28,74"}}
