  const pdu=t.closest("[data-popdup]");if(pdu){const L2=D.popup.items,i=+pdu.dataset.popdup,c=clone(L2[i]);c.on=false;if(c.name)c.name={en:(c.name.en||"")+" (copy)",pt:(c.name.pt||"")+" (cópia)"};L2.splice(i+1,0,c);changed(true);return}
