  const orr=t.closest("[data-ovreset]");if(orr){const hm=orr.dataset.home==="1";set(D,orr.dataset.ovreset+".overlay",{left:90,right:hm?20:40,bottom:hm?100:0,color:"navy"});changed(true);return}
  const ptd=t.closest("[data-pdftoday]");if(ptd){set(D,ptd.dataset.pdftoday,new Date().toISOString().slice(0,10));changed(true);return}
  if(t.closest("[data-today]")){D.berth.updated=new Date().toISOString().slice(0,10);changed(true);return}
  if(t.closest("[data-newpage]")){const ti=$("#np_title").value.trim(),sl=($("#np_slug").value.trim()||ti).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
    if(!ti||!sl)return toast("Indique o título da página.");if(D.pages[sl]||sl==="home")return toast("Já existe uma página com esse endereço.");
    D.pages[sl]={type:"content",title:T(ti,""),group:T("",""),eyebrow:T("",""),intro:T("",""),body:T("",""),items:[],specs:[],docs:[],docSections:[],image:"",badge:T("","")};editPage=sl;changed(true);return}
  if(t.closest("[data-delpage]")){delete D.pages[editPage];D.home.facilities.pages=D.home.facilities.pages.filter(k=>k!==editPage);editPage=null;confirmKey=null;changed(true);return}
  if(t.closest("[data-loadremote]")){draft=hydrate(published);dirty=false;remoteChanged=false;renderAll(true);return}
  const rd=t.closest("[data-read]");if(rd){await Store.inboxUpdate(rd.dataset.read,{read:rd.dataset.v==="1"},l=>{inbox=l;renderNav();renderMain(true)});return}
  const md=t.closest("[data-mdel]");if(md){confirmKey=null;await Store.inboxUpdate(md.dataset.mdel,null,l=>{inbox=l;renderNav();renderMain(true)});toast("Mensagem apagada");return}
  if(t.closest("[data-copy]")){const txt=JSON.stringify(published||{});try{await navigator.clipboard.writeText(txt);toast("JSON copiado")}catch(err){toast("Não foi possível copiar. Use Descarregar JSON.")}return}
  if(t.closest("[data-dl]")){const txt=JSON.stringify(published||{},null,1),fn="port-of-beira-conteudo.json";
    if(Store.downloads){try{await Store.downloads.save({filename:fn,data:txt})}catch(err){if(err&&err.code!=="cancelled")toast("Não foi possível descarregar. Use Copiar JSON.")}return}
    const u=URL.createObjectURL(new Blob([txt],{type:"application/json"})),l=document.createElement("a");l.href=u;l.download=fn;document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);return}
  if(t.closest("[data-import]")){doImport($("#f_import").value);return}
