/* ---------- Supabase: sessão, editores e histórico ---------- */
function SB_ACCESS(){const me=esc(Store.auth.email);
  return `<div class="card"><div class="card-h"><h3>Sessão</h3></div><p>Ligado como <b>${me}</b>.</p><div class="g2"><div class="f"><label for="f_np">Nova palavra-passe</label><input type="password" id="f_np" autocomplete="new-password"></div><div class="f"><label for="f_np2">Confirmar</label><input type="password" id="f_np2" autocomplete="new-password"></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn add" data-sbpass>Alterar palavra-passe</button><button class="btn" data-logout>Terminar sessão</button></div></div>
  <div class="card"><div class="card-h"><h3>Editores</h3></div><span class="hint">Pessoas que podem publicar e ler as mensagens. Depois de adicionar o email, a pessoa cria a conta em “Criar conta” na entrada do gestor (ou é convidada no painel do Supabase).</span><div id="sbEd" class="sbl"><p class="hint">A carregar…</p></div><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end"><div class="f" style="flex:1;min-width:220px"><label for="f_edmail">Email do novo editor</label><input type="email" id="f_edmail" autocomplete="off" placeholder="nome@cornelder.co.mz"></div><button class="btn add" data-edadd>Adicionar editor</button></div></div>
  <div class="card"><div class="card-h"><h3>Histórico de publicações</h3></div><span class="hint">Cada publicação guarda a versão anterior. Abra uma versão no rascunho para a rever e volte a publicar se quiser repô-la.</span><div id="sbHist" class="sbl"><p class="hint">A carregar…</p></div></div>`}
async function sbFill(){const ed=$("#sbEd"),hi=$("#sbHist");const en=cmsLang==="en";
  if(ed)try{const l=await Store.auth.editors(),me=Store.auth.email.toLowerCase();ed.innerHTML=l.length?l.map(x=>`<div class="sbrow"><span>${esc(x.email)}${x.email.toLowerCase()===me?` <small class="tag">${en?"you":"você"}</small>`:""}</span>${x.email.toLowerCase()===me?"":confirmKey==="ed"+x.email?`<span><button class="btn del" data-eddel="${esc(x.email)}">${en?"Yes, remove":"Sim, remover"}</button> <button class="btn" data-nocf>${en?"Cancel":"Cancelar"}</button></span>`:`<button class="btn del" data-cf="ed${esc(x.email)}">${en?"Remove":"Remover"}</button>`}</div>`).join(""):`<p class="hint">—</p>`}catch(e){ed.innerHTML=`<p class="hint">${en?"Could not load the list.":"Não foi possível carregar a lista."}</p>`}
  if(hi)try{const l=await Store.auth.history();hi.innerHTML=l.length?l.map(x=>`<div class="sbrow"><span>${new Date(x.saved_at).toLocaleString(LOC(),{dateStyle:"medium",timeStyle:"short"})}${x.saved_by?` · <small>${esc(x.saved_by)}</small>`:""}</span><button class="btn" data-histload="${esc(String(x.id))}">${en?"Open in draft":"Abrir no rascunho"}</button></div>`).join(""):`<p class="hint">${en?"No earlier versions yet. They appear after the second publication.":"Ainda sem versões anteriores. Aparecem a partir da segunda publicação."}</p>`}catch(e){hi.innerHTML=`<p class="hint">${en?"Could not load the history.":"Não foi possível carregar o histórico."}</p>`}}
function sbMsg(e){const m=String(e&&e.message||e||"");
  if(/invalid login|invalid_credentials|Invalid login credentials/i.test(m))return"Email ou palavra-passe incorrectos.";
  if(/not confirmed|email_not_confirmed/i.test(m))return"Confirme primeiro o email através da mensagem que recebeu.";
  if(/already registered|user_already_exists/i.test(m))return"Este email já tem conta. Use Entrar ou Esqueci a palavra-passe.";
  if(/signups? not allowed|signup_disabled/i.test(m))return"A criação de contas está desactivada. Peça um convite ao administrador.";
  if(/password should be|weak_password/i.test(m))return"Palavra-passe fraca: use pelo menos 8 caracteres.";
  if(/rate limit|over_email_send_rate_limit|429/i.test(m))return"Demasiados pedidos. Aguarde alguns minutos e tente de novo.";
  if(/Failed to fetch|NetworkError|Load failed/i.test(m))return"Sem ligação ao Supabase. Verifique a internet e o config.js.";
  return"Erro: "+m}
document.addEventListener("click",e=>{if(e.target.closest("[data-reload]"))location.reload()});
document.addEventListener("click",async e=>{const t=e.target;if(Store.mode!=="supabase")return;
  if(t.closest("[data-logout]")){if(dirty&&!confirm(cmsLang==="en"?"There are unpublished changes. Sign out anyway?":"Há alterações por publicar. Terminar a sessão mesmo assim?"))return;dirty=false;await Store.auth.signOut();location.reload();return}
  if(!draft)return;
  if(t.closest("[data-sbpass]")){const a=$("#f_np").value,b=$("#f_np2").value;if(a.length<8)return toast("Use pelo menos 8 caracteres.");if(a!==b)return toast("As palavras-passe não coincidem.");try{await Store.auth.setPassword(a);$("#f_np").value=$("#f_np2").value="";toast("Palavra-passe alterada")}catch(err){toast(sbMsg(err))}return}
  if(t.closest("[data-edadd]")){const v=$("#f_edmail").value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v))return toast("Indique um email válido.");try{await Store.auth.addEditor(v);$("#f_edmail").value="";toast("Editor adicionado");sbFill()}catch(err){toast(/duplicate|23505|409/i.test(String(err.message)+err.status)?"Este email já é editor.":sbMsg(err))}return}
  const dd=t.closest("[data-eddel]");if(dd){confirmKey=null;try{await Store.auth.removeEditor(dd.dataset.eddel);toast("Editor removido")}catch(err){toast(sbMsg(err))}sbFill();return}
  const hl=t.closest("[data-histload]");if(hl){try{const b=await Store.auth.version(hl.dataset.histload);if(!b)return toast("Versão não encontrada.");draft=hydrate(b);changed(true);renderAll(true);toast("Versão aberta no rascunho. Reveja e clique em Publicar para a repor.")}catch(err){toast(sbMsg(err))}return}
});
async function sbGate(){const A=Store.auth,en=()=>cmsLang==="en";
  let via=null;try{via=await A.fromLink()}catch(e){}
  if(via==="recovery"||via==="invite"){
    gate(`<img src="${LOGO_WHITE}" alt="Cornelder de Moçambique" style="width:220px;height:auto"><h1>Definir palavra-passe</h1><p>${esc(A.email)}</p><form id="pf" style="display:flex;flex-direction:column;gap:14px"><div class="f"><label for="np1">Nova palavra-passe</label><input type="password" id="np1" autocomplete="new-password" minlength="8" required></div><div class="f"><label for="np2">Confirmar</label><input type="password" id="np2" autocomplete="new-password" minlength="8" required></div><p class="err" id="lerr" hidden></p><button class="tbtn pub" type="submit">Guardar e entrar</button></form>`);
    $("#pf").addEventListener("submit",async ev=>{ev.preventDefault();const a=$("#np1").value,b=$("#np2").value,er=$("#lerr");er.hidden=true;
      if(a!==b){er.textContent=en()?"Passwords do not match.":"As palavras-passe não coincidem.";er.hidden=false;return}
      try{await A.setPassword(a);sbEnter()}catch(err){er.textContent=en()?trText(sbMsg(err)):sbMsg(err);er.hidden=false}});return}
  if(A.session){sbEnter();return}
  sbLogin()}
function sbLogin(view){view=view||"in";const en=cmsLang==="en";
  const title={in:"Gestor de conteúdos",up:"Criar conta",fp:"Recuperar palavra-passe"}[view];
  gate(`<img src="${LOGO_WHITE}" alt="Cornelder de Moçambique" style="width:220px;height:auto"><h1>${title}</h1><p>Port of Beira · site institucional</p><form id="lf" style="display:flex;flex-direction:column;gap:14px"><div class="f"><label for="em">Email</label><input type="email" id="em" autocomplete="username" required></div>${view==="fp"?"":`<div class="f"><label for="pw">Palavra-passe</label><input type="password" id="pw" autocomplete="${view==="up"?"new-password":"current-password"}" ${view==="up"?'minlength="8"':""} required></div>`}${view==="up"?`<p class="note">Só consegue publicar se o seu email tiver sido adicionado como editor.</p>`:""}<p class="err" id="lerr" hidden></p><p class="note" id="lok" hidden></p><button class="tbtn pub" type="submit">${view==="in"?"Entrar":view==="up"?"Criar conta":"Enviar link de recuperação"}</button></form><p class="gate-links">${view!=="in"?`<button class="lnkbtn" data-sbv="in">Voltar à entrada</button>`:`<button class="lnkbtn" data-sbv="fp">Esqueci a palavra-passe</button> · <button class="lnkbtn" data-sbv="up">Criar conta</button>`}</p>`);
  $("#em").focus();
  $("#gate").querySelectorAll("[data-sbv]").forEach(b=>b.addEventListener("click",()=>sbLogin(b.dataset.sbv)));
  $("#lf").addEventListener("submit",async ev=>{ev.preventDefault();const er=$("#lerr"),ok=$("#lok"),btn=$("#lf button[type=submit]"),em=$("#em").value.trim(),pw=$("#pw")&&$("#pw").value;er.hidden=ok.hidden=true;btn.disabled=true;
    const say=(el,m)=>{el.textContent=cmsLang==="en"?trText(m):m;el.hidden=false};
    try{if(view==="in"){await Store.auth.signIn(em,pw);welcomeNext=true;sbEnter();return}
      if(view==="up"){const r=await Store.auth.signUp(em,pw);if(Store.auth.session){welcomeNext=true;sbEnter();return}say(ok,"Conta criada. Abra o email de confirmação que lhe enviámos e depois entre.")}
      if(view==="fp"){await Store.auth.recover(em,location.href.split("#")[0]);say(ok,"Se o email existir, recebe um link para definir uma nova palavra-passe.")}}
    catch(err){say(er,sbMsg(err))}btn.disabled=false})}
async function sbEnter(){const ok=await Store.auth.isEditor();
  if(!ok){if(!Store.auth.session){sbLogin();return}
    gate(`<img src="${LOGO_WHITE}" alt="Cornelder de Moçambique" style="width:220px;height:auto"><h1>Sem acesso de edição</h1><p><span>A conta</span> <b>${esc(Store.auth.email)}</b> <span>ainda não está na lista de editores. Peça a um editor que a adicione em Dados e acesso.</span></p><button class="tbtn pub" data-logout>Entrar com outra conta</button><a class="tbtn ghost" href="./">Ver o site</a>`);return}
  start()}
